def transform(grid):
    # Identify marker rows where pattern values appear: [0, 4, 8, 12]
    marker_rows = [0, 4, 8, 12]

    # Find all marker columns by checking where non-background values appear
    all_marker_cols = set()
    for r in marker_rows:
        for c in range(len(grid[r])):
            if grid[r][c] != 5:  # 5 is the background separator color
                all_marker_cols.add(c)

    marker_cols = sorted(list(all_marker_cols))

    # Extract the marker grid with background replacement (5 -> 8)
    output = []
    for r in marker_rows:
        row_out = []
        for c in marker_cols:
            val = grid[r][c]
            if val == 5:
                row_out.append(8)
            else:
                row_out.append(val)
        output.append(row_out)

    return output
